<!-- VideoPlayer.vue -->
<template>
  <!-- v-for="item in viewVideoList"
    :key="item?.deviceId"
    @click="onView(item)" -->
  <div>
    <!-- <template v-if="isShow"> -->
    <div
      style="width: 100%; height: 100%"
      v-for="item in viewVideoList"
      :key="item?.deviceId"
    >
      <video
        :class="'videoElement' + item.deviceId"
        controls
        autoplay
        muted
        style="width: 100%; height: 100%"
      ></video>
    </div>
    <!-- </template> -->
  </div>
</template>

<script>
window.addEventListener("error", (e) => {
  console.log("error", e);
});
import flvjs from "flv.js/dist/flv.min.js";
export default {
  name: "VideoPlayer",
  props: {
    url: {
      type: Array,
    },
  },
  data() {
    return {
      //历史的播放数据
      history: [],
      //新的
      viewVideoList: [],
      isShow: true,
    };
  },
  watch: {
    url: function (newsFle, old) {
      console.log("cccccccccc", newsFle, old);
      if (this.history.length > 0) {
        console.log("this.historythis.history222", this.history);
        this.history.map((item, index) => {
          console.log(item.pause);
          setTimeout(() => {
            item.pause();
            item.unload();
            item.detachMediaElement();
            item.destroy();
            this.history.splice(index);
          }, 1000);
          // item.pause();
          // item.unload();
          // item.detachMediaElement();
          // item.destroy();
        });
      }
      this.viewVideoList = newsFle;
      if (newsFle.length != 0) {
        this.$nextTick(() => {
          this.init();
        });
      } else {
        // this.viewVideoList = JSON.parse(JSON.stringify(old));
      }
    },
  },

  mounted() {
    // let str = window.location.href;
    // let searchText = "adress=";
    // let index = str.indexOf(searchText);
    // let adress = "/api";
    // if (index !== -1) {
    // adress += str.substring(index + searchText.length);
  },
  methods: {
    init() {
      if (!this.viewVideoList.length) return;
      try {
        let arrDomFlv = [];
        this.viewVideoList.map((item) => {
          let dom = document.getElementsByClassName(
            "videoElement" + item.deviceId
          )[0];
          if (flvjs.isSupported()) {
            let flvPlayer = flvjs.createPlayer(
              {
                type: "flv",
                enableWorker: true,
                isLive: true,
                hasAudio: false,
                hasVideo: true,
                stashInitialSize: 40,
                enableStashBuffer: true,
                url: item.url,
              },
              { autoCleanupSourceBuffer: true }
            );
            flvPlayer.attachMediaElement(dom);
            flvPlayer.load();
            flvPlayer.play();
            console.log(flvPlayer);

            arrDomFlv.push(flvPlayer);
          } else if (dom.canPlayType("application/vnd.apple.mpegurl")) {
            dom.src = this.src;
            dom.addEventListener("canplay", () => {
              dom.play().catch((e) => {
                console.log(e);
              });
            });
          }
        });
        this.history = arrDomFlv;
        console.log("this.history", this.history);
      } catch (error) {
        console.log(error);
      }
    },
  },
};
</script>

