import request from "../utils/request/request.js";
//监控树
export function deviceTree() {
  return request({
    url: "/api/aiVideo/device/tree",
    method: "get",
  });
}
//监控树视频列表
export function deviceTreeList() {
  return request({
    url: "/api/aiVideo/device/list",
    method: "get",
  });
}
