<script>
import JIANKONG from "./jiankong.vue";
import { deviceTree, deviceTreeList } from "../api/monitor";
export default {
  components: {
    JIANKONG,
  },
  data() {
    return {
      //弹出层
      drawer: false,
      treeData: [],
      props: {
        label: "nodeName",
        children: "children",
      },
      // count: 1,
      viewVideoList: [],
      direction: "ltr",
      //监控列表全部数据
      treeDataViewList: [],
      //选中的数据
      changeTreeDataViewList: [],
      arr: [],
    };
  },
  mounted() {
    let urlText = window.location.href;
    let startText = "?token=";
    let index = urlText.indexOf(startText);
    if (index !== -1) {
      let result = urlText.substring(index + startText.length);
      localStorage.setItem("token", result);
      this.getDeviceTree();
      this.getDeviceTreeList();
    } else {
      console.log("没有token或失效", window.location);
    }
  },
  methods: {
    handleClose() {
      this.viewVideoList = this.arr;
      this.drawer = !this.drawer;
    },
    handleCheckChange(data, checked) {
      console.log(data, checked);
      if (this.treeDataViewList.length > 0) {
        this.arr = [];
        this.treeDataViewList.map((item1) => {
          checked.checkedKeys.map((item2) => {
            if (item1.deviceId == item2) {
              item1.url =
                item1.playAddress.replace(
                  "http://58.56.223.174:18080",
                  "/api"
                ) + ".flv";
              this.arr.push(item1);
            }
          });
          // return item.deviceId == currentItem.key
        });
      }
    },
    async loadNode(node, resolve) {
      console.log(node, resolve);
      if (node.level === 0) {
        let arr = [];
        let res = await deviceTree();
        arr = res.data.data.map((item) => {
          return {
            nodeName: item.nodeName,
          };
        });
        return resolve(arr);
      }
      if (node.level > 3) return resolve([]);

      // var hasChild;
      // if (node.data.name === "电碳成品区域") {
      //   hasChild = true;
      // } else if (node.data.name === "region2") {
      //   hasChild = false;
      // } else {
      //   hasChild = Math.random() > 0.5;
      // }
      deviceTreeList().then((res) => {
        res.data.data.map();
        console.log("监控树视频列表", res);
      });
      resolve([
        {
          nodeName: "nodeName" + this.count++,
        },
        {
          nodeName: "nodeName" + this.count++,
        },
      ]);
    },
    onDrawer() {
      this.drawer = !this.drawer;
    },
    getDeviceTree() {
      deviceTree().then((res) => {
        this.treeData = res.data.data;
      });
    },
    getDeviceTreeList() {
      deviceTreeList().then((res) => {
        this.treeDataViewList = res.data.data;
      });
    },
  },
};
</script>

